package com.example.myapplication;

import android.graphics.*;
import com.tom_roush.pdfbox.pdmodel.*;
import com.tom_roush.pdfbox.pdmodel.common.PDRectangle;
import com.tom_roush.pdfbox.pdmodel.graphics.color.*;
import com.tom_roush.pdfbox.pdmodel.interactive.annotation.*;
import com.tom_roush.pdfbox.cos.*;
import org.json.*;
import java.util.*;
import java.util.function.Supplier;

/** Editable annotation geometry is normalized to the displayed (rotated, cropped) page. */
final class PdfAnnotations {
    static class Mark {int page,color=0xff1252cc;String tool,text="",origin="";Integer fillColor;RectF bounds=new RectF();ArrayList<Float> points=new ArrayList<>(),quads=new ArrayList<>();ArrayList<ArrayList<Float>> strokes=new ArrayList<>();float width=1.5f,opacity=1;}
    static boolean supported(PDAnnotation a){String type=a.getSubtype();return !a.isLocked()&&!a.isReadOnly()&&Arrays.asList("Highlight","Underline","StrikeOut","Square","Ink","Text").contains(type);}
    static void remove(PDDocument doc)throws Exception{for(PDPage page:doc.getPages()){ArrayList<PDAnnotation> kept=new ArrayList<>();for(PDAnnotation a:page.getAnnotations()){if(supported(a))continue;if(a instanceof PDAnnotationPopup&&((PDAnnotationPopup)a).getParent()!=null&&supported(((PDAnnotationPopup)a).getParent()))continue;kept.add(a);}page.setAnnotations(kept);}}
    static float[] display(PDPage page,float x,float y){PDRectangle b=page.getCropBox();float X=(x-b.getLowerLeftX())/b.getWidth(),Y=(y-b.getLowerLeftY())/b.getHeight();switch((page.getRotation()%360+360)%360){case 90:return new float[]{Y,X};case 180:return new float[]{1-X,Y};case 270:return new float[]{1-Y,1-X};default:return new float[]{X,1-Y};}}
    static <M extends Mark> ArrayList<M> read(PDDocument doc,Supplier<M> factory)throws Exception{ArrayList<M> result=new ArrayList<>();for(int page=0;page<doc.getNumberOfPages();page++){PDPage p=doc.getPage(page);int annotationIndex=0;for(PDAnnotation a:p.getAnnotations()){String origin=page+"-"+annotationIndex++;if(!supported(a)||a.getRectangle()==null)continue;M m=factory.get();m.origin=origin;m.page=page;m.tool=a.getSubtype().equals("Square")?"Rectangle":a.getSubtype().equals("Text")?"Comment":a.getSubtype().equals("Ink")?"Pen":a.getSubtype().equals("StrikeOut")?"Strikeout":a.getSubtype();m.text=a.getContents()==null?"":a.getContents();try{if(a.getColor()!=null)m.color=0xff000000|a.getColor().toRGB();}catch(Exception ignored){}if(a instanceof PDAnnotationSquareCircle&&((PDAnnotationSquareCircle)a).getInteriorColor()!=null)try{m.fillColor=0xff000000|((PDAnnotationSquareCircle)a).getInteriorColor().toRGB();}catch(Exception ignored){}if(a instanceof PDAnnotationMarkup)m.opacity=((PDAnnotationMarkup)a).getConstantOpacity();PDRectangle box=a.getRectangle();float[] one=display(p,box.getLowerLeftX(),box.getLowerLeftY()),two=display(p,box.getUpperRightX(),box.getUpperRightY());m.bounds.set(Math.min(one[0],two[0]),Math.min(one[1],two[1]),Math.max(one[0],two[0]),Math.max(one[1],two[1]));COSBase border=a.getCOSObject().getDictionaryObject(COSName.BS);if(border instanceof COSDictionary)m.width=((COSDictionary)border).getFloat(COSName.W,1.5f);
            if(a instanceof PDAnnotationTextMarkup){float[] quads=((PDAnnotationTextMarkup)a).getQuadPoints();if(quads!=null)for(int i=0;i+1<quads.length;i+=2){float[] q=display(p,quads[i],quads[i+1]);m.quads.add(q[0]);m.quads.add(q[1]);}}
            if(m.tool.equals("Pen")&&a instanceof PDAnnotationMarkup){float[][] ink=((PDAnnotationMarkup)a).getInkList();if(ink!=null)for(float[] stroke:ink){ArrayList<Float> points=new ArrayList<>();for(int i=0;i+1<stroke.length;i+=2){float[] q=display(p,stroke[i],stroke[i+1]);points.add(q[0]);points.add(q[1]);}m.strokes.add(points);}if(!m.strokes.isEmpty())m.points.addAll(m.strokes.get(0));}result.add(m);
        }}return result;}
    static void append(PDDocument doc,Mark m)throws Exception{PDPage page=doc.getPage(m.page);RectF r=m.bounds;float[] tl=PdfEditActivity.point(page,r.left,r.top),tr=PdfEditActivity.point(page,r.right,r.top),bl=PdfEditActivity.point(page,r.left,r.bottom),br=PdfEditActivity.point(page,r.right,r.bottom);PDAnnotation a;PDColor color=new PDColor(new float[]{Color.red(m.color)/255f,Color.green(m.color)/255f,Color.blue(m.color)/255f},PDDeviceRGB.INSTANCE);
        if(Arrays.asList("Highlight","Underline","Strikeout").contains(m.tool)){PDAnnotationTextMarkup mark=new PDAnnotationTextMarkup(m.tool.equals("Strikeout")?"StrikeOut":m.tool);float[] quads;if(m.quads.isEmpty())quads=new float[]{tl[0],tl[1],tr[0],tr[1],bl[0],bl[1],br[0],br[1]};else{quads=new float[m.quads.size()];for(int i=0;i+1<quads.length;i+=2){float[] q=PdfEditActivity.point(page,m.quads.get(i),m.quads.get(i+1));quads[i]=q[0];quads[i+1]=q[1];}}mark.setQuadPoints(quads);a=mark;
        }else if(m.tool.equals("Comment")){PDAnnotationText mark=new PDAnnotationText();mark.setName(PDAnnotationText.NAME_COMMENT);mark.setContents(m.text);a=mark;
        }else if(m.tool.equals("Pen")){PDAnnotationMarkup mark=new PDAnnotationMarkup();mark.getCOSObject().setName(COSName.SUBTYPE,"Ink");List<ArrayList<Float>> strokes=m.strokes.isEmpty()?Collections.singletonList(m.points):m.strokes;float[][] ink=new float[strokes.size()][];for(int s=0;s<strokes.size();s++){List<Float> points=strokes.get(s);ink[s]=new float[points.size()];for(int i=0;i+1<points.size();i+=2){float[] q=PdfEditActivity.point(page,points.get(i),points.get(i+1));ink[s][i]=q[0];ink[s][i+1]=q[1];}}mark.setInkList(ink);a=mark;
        }else{PDAnnotationSquareCircle square=new PDAnnotationSquareCircle("Square");if(m.fillColor!=null)square.setInteriorColor(new PDColor(new float[]{Color.red(m.fillColor)/255f,Color.green(m.fillColor)/255f,Color.blue(m.fillColor)/255f},PDDeviceRGB.INSTANCE));a=square;}
        float left=Math.min(tl[0],br[0]),bottom=Math.min(tl[1],br[1]),right=Math.max(tl[0],br[0]),top=Math.max(tl[1],br[1]);float margin=m.tool.equals("Pen")?m.width:0;a.setRectangle(new PDRectangle(left-margin,bottom-margin,Math.max(1,right-left+margin*2),Math.max(1,top-bottom+margin*2)));a.setColor(color);if(a instanceof PDAnnotationMarkup)((PDAnnotationMarkup)a).setConstantOpacity(m.opacity);PDBorderStyleDictionary border=new PDBorderStyleDictionary();border.setWidth(m.width);a.getCOSObject().setItem(COSName.BS,border);a.setPrinted(true);a.constructAppearances(doc);page.getAnnotations().add(a);
    }
    static void apply(PDDocument doc,List<? extends Mark> marks)throws Exception{ArrayList<Mark> originals=read(doc,Mark::new);HashMap<String,String> before=new HashMap<>();for(Mark m:originals)before.put(m.origin,encode(Collections.singletonList(m)));HashMap<String,Mark> current=new HashMap<>();for(Mark m:marks)if(!m.origin.isEmpty())current.put(m.origin,m);HashMap<COSDictionary,String> parentIds=new HashMap<>();for(int p=0;p<doc.getNumberOfPages();p++){int at=0;for(PDAnnotation a:doc.getPage(p).getAnnotations()){if(supported(a))parentIds.put(a.getCOSObject(),p+"-"+at);at++;}}for(int page=0;page<doc.getNumberOfPages();page++){ArrayList<PDAnnotation> kept=new ArrayList<>();int index=0;for(PDAnnotation a:doc.getPage(page).getAnnotations()){String key=page+"-"+index++;if(!supported(a)){if(a instanceof PDAnnotationPopup&&((PDAnnotationPopup)a).getParent()!=null){String parent=parentIds.get(((PDAnnotationPopup)a).getParent().getCOSObject());if(parent!=null){Mark edited=current.get(parent);if(edited==null||!encode(Collections.singletonList(edited)).equals(before.get(parent)))continue;}}kept.add(a);continue;}Mark after=current.get(key);if(after!=null&&encode(Collections.singletonList(after)).equals(before.get(key)))kept.add(a);}doc.getPage(page).setAnnotations(kept);}for(Mark m:marks)if(!m.tool.equals("Redact")&&!m.tool.equals("Replace text")&&(m.origin.isEmpty()||!encode(Collections.singletonList(m)).equals(before.get(m.origin))))append(doc,m);}
    static String encode(List<? extends Mark> marks)throws Exception{JSONArray array=new JSONArray();for(Mark m:marks)array.put(new JSONObject().put("page",m.page).put("origin",m.origin).put("fill",m.fillColor).put("tool",m.tool).put("text",m.text).put("rect",new JSONArray(new float[]{m.bounds.left,m.bounds.top,m.bounds.right,m.bounds.bottom})).put("points",new JSONArray(m.points)).put("quads",new JSONArray(m.quads)).put("strokes",new JSONArray(m.strokes)).put("color",m.color).put("width",m.width).put("opacity",m.opacity));return array.toString();}
    static <M extends Mark> ArrayList<M> decode(String json,Supplier<M> factory)throws Exception{JSONArray array=new JSONArray(json);ArrayList<M> result=new ArrayList<>();for(int i=0;i<array.length();i++){JSONObject o=array.getJSONObject(i);M m=factory.get();m.page=o.getInt("page");m.origin=o.optString("origin");m.fillColor=o.has("fill")&&!o.isNull("fill")?o.getInt("fill"):null;m.tool=o.getString("tool");m.text=o.optString("text");m.color=o.optInt("color",0xff1252cc);m.width=(float)o.optDouble("width",1.5);m.opacity=(float)o.optDouble("opacity",1);JSONArray r=o.getJSONArray("rect");m.bounds.set((float)r.getDouble(0),(float)r.getDouble(1),(float)r.getDouble(2),(float)r.getDouble(3));numbers(o.optJSONArray("points"),m.points);numbers(o.optJSONArray("quads"),m.quads);JSONArray paths=o.optJSONArray("strokes");if(paths!=null)for(int j=0;j<paths.length();j++){ArrayList<Float> stroke=new ArrayList<>();numbers(paths.getJSONArray(j),stroke);m.strokes.add(stroke);}result.add(m);}return result;}
    private static void numbers(JSONArray values,List<Float> target)throws Exception{if(values!=null)for(int i=0;i<values.length();i++)target.add((float)values.getDouble(i));}
    static void move(Mark m,float dx,float dy){m.bounds.offset(dx,dy);move(m.points,dx,dy);move(m.quads,dx,dy);for(List<Float> stroke:m.strokes)move(stroke,dx,dy);}
    private static void move(List<Float> points,float dx,float dy){for(int i=0;i+1<points.size();i+=2){points.set(i,points.get(i)+dx);points.set(i+1,points.get(i+1)+dy);}}
}
